# Avarma / Hofman Parameterliste – Display-Nummerierung, Display-Skalierung (abgeglichen mit Fotos 19.10.2026)
# (P, scale, unit, min, max, level U=Benutzer(Code 99, blau)/T=Techniker(weiß)/X=gesperrt, group, name, Erklärung)
def addr(p):
    if p in (0, 1): return 8192 + p
    if 2 <= p <= 5: return 4096 + p          # Steuerblock: P02..P05 = 4098..4101
    if 6 <= p <= 104: return 8190 + p
    if p in (105, 106): return 8194 + (p - 105)
    if 107 <= p <= 120: return 8188 + p
    if 121 <= p <= 150: return 8190 + p
    if 201 <= p <= 208: return 4864 + (p - 201)   # SG-Ready PSG1..8
    raise ValueError(p)

